    def xǁMemoryManagerǁformat_memory_age__mutmut_orig(self, memory: MemoryRecord) -> str:
        """
        Format memory age in human-readable form.
        
        Args:
            memory: MemoryRecord to format age for
            
        Returns:
            Human-readable age string (e.g., "3 days ago", "2 hours ago")
        """
        age = self.calculate_memory_age(memory)
        
        if age.days > 0:
            if age.days == 1:
                return "1 day ago"
            return f"{age.days} days ago"
        elif age.seconds >= 3600:
            hours = age.seconds // 3600
            if hours == 1:
                return "1 hour ago"
            return f"{hours} hours ago"
        elif age.seconds >= 60:
            minutes = age.seconds // 60
            if minutes == 1:
                return "1 minute ago"
            return f"{minutes} minutes ago"
        else:
            return "just now"
    
